WITH cleaned AS (SELECT *, ABS(balance) AS abs_balance, ROUND(balance, 0) AS balance_rounded FROM accounts WHERE opened_date > DATE '2023-06-11') SELECT DATE_TRUNC('MONTH', opened_date) AS activity_month, ROUND(SUM(balance_rounded) / NULLIF(COUNT(CASE WHEN account_type = 'LOAN' THEN 1 END), 0), 2) AS balance_rounded_per_loan, COUNT_IF(account_type = 'CREDIT') AS credit_events, COUNT_IF(account_type = 'SAVINGS') AS savings_events, PERCENTILE_APPROX(balance_rounded, 0.95) AS balance_rounded_p95, COUNT(DISTINCT status) AS distinct_status, COUNT(*) FILTER (WHERE status = 'CLOSED') AS closed_rows FROM cleaned GROUP BY DATE_TRUNC('MONTH', opened_date) ORDER BY distinct_status DESC NULLS FIRST;
